    s2Title: "Dịch vụ UVEL",
    s2Body:
      "UVEL điều phối các tác vụ suy luận AI và dựng hình tới phần cứng UVELBox và UVELRack do người tham gia sở hữu, đồng thời cung cấp dịch vụ ghép nối, thanh toán và ví. Chúng tôi không đảm bảo luôn có tác vụ, giá cố định hay một mức nhu cầu tính toán cụ thể nào. Điều khoản đã công bố có hiệu lực áp dụng.",
    s3Title: "Tài khoản & bảo mật của bạn",
    s3Body:
      "Bạn có trách nhiệm bảo vệ thông tin đăng nhập, xác thực hai lớp và khóa ví của mình. Mọi hoạt động dưới tài khoản của bạn là trách nhiệm của bạn. Hãy báo cho chúng tôi ngay nếu có truy cập trái phép. Chúng tôi có thể tạm khóa các tài khoản có dấu hiệu gian lận, mở nhiều tài khoản hoặc lộ thông tin đăng nhập.",
    s4Title: "Mua & vận hành phần cứng",
    s4Body:
      "Giao dịch mua UVELBox / UVELRack là cuối cùng khi thiết bị đã được kích hoạt trên mạng lưới. Công suất thiết bị giảm theo thời gian sử dụng và thu nhập có thể giảm theo; xem Công bố rủi ro. Thiết bị đã mua có thể đổi lên thiết bị mạnh hơn theo quy tắc hiển thị trên trang nâng cấp.",
    s5Title: "Thu nhập, phần thưởng & token UVT",
    s5Body:
      "Mọi con số thu nhập hiển thị trong ứng dụng đều là ước tính dựa trên tham số mạng lưới hiện tại và nhu cầu gần đây, không phải cam kết. Thu nhập có thể biến động và giảm theo thời gian. UVT là token thưởng của nền tảng, giá trị có thể biến động mạnh và không được bảo hiểm tiền gửi. Đừng bao giờ bỏ ra số tiền nhiều hơn mức bạn có thể chấp nhận mất.",
    s6Title: "Ví, rút tiền & tuân thủ",
    s6Body: "Tiền rút chuyển vào địa chỉ rút tiền do chính bạn thiết lập (xác nhận qua SMS, đổi được bất cứ lúc nào; sau khi đổi có thời gian bảo vệ an toàn). Thời gian xử lý theo trạng thái lệnh. Số tiền vượt ngưỡng công bố có thể cần thêm một bước xác nhận an toàn.",
    s7Title: "Phần thưởng giới thiệu & mạng lưới",
    s7Body:
      "Thưởng mời bạn được chi trả theo quy tắc của nền tảng và phụ thuộc vào việc người được mời hoàn thành các hành động hợp lệ. Spam, tài khoản giả hay đăng ký hàng loạt đều bị cấm; các khoản thưởng liên quan sẽ bị hủy và có thể dẫn tới khóa tài khoản cùng hủy các khoản thưởng đang chờ.",
    s8Title: "Hành vi bị cấm",
    s8Body:
      "Bạn không được dùng UVEL để rửa tiền, thao túng thị trường token, né các cơ chế an toàn, mở nhiều tài khoản để cày thưởng, dịch ngược hay can thiệp vào mạng lưới, hoặc gây nhiễu tới thiết bị của người tham gia khác. Vi phạm có thể dẫn tới chấm dứt ngay lập tức và báo cáo lên các cơ quan có thẩm quyền.",
    s9Title: "Phí, thuế & thay đổi",
    s9Body:
      "Phí mạng lưới, phí rút tiền và phí xử lý thẻ được công bố ngay tại mỗi giao dịch. Bạn tự chịu trách nhiệm về mọi khoản thuế phát sinh trên thu nhập của mình. Chúng tôi có thể cập nhật các điều khoản này; thay đổi quan trọng sẽ được thông báo trong ứng dụng, và việc tiếp tục sử dụng sau ngày hiệu lực nghĩa là bạn chấp nhận.",
    s10Title: "Miễn trừ, trách nhiệm & luật áp dụng",
    s10Body:
      "UVEL được cung cấp “nguyên trạng”, không có bất kỳ bảo đảm nào về lợi nhuận. Trong phạm vi tối đa pháp luật cho phép, tổng trách nhiệm của chúng tôi giới hạn ở khoản phí bạn đã trả trong ba tháng gần nhất. Các điều khoản này được điều chỉnh theo pháp luật tại khu vực tài phán của UVEL Compliance Authority, và tranh chấp được giải quyết bằng trọng tài có tính ràng buộc ở nơi được phép.",
